using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public static class ModelTrainingService
{
    public static string TrainAndSaveModel(IConfiguration configuration)
    {
        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");

        var mlContext = new MLContext(seed: 42);

        IDataView data = mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        // Featurize text columns and combine with Priority
        var pipeline = mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        Console.WriteLine("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        // Evaluate on test set
        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

        Console.WriteLine("===== Model Evaluation Metrics =====");
        Console.WriteLine($"MacroAccuracy:    {metrics.MacroAccuracy:F4}");
        Console.WriteLine($"MicroAccuracy:    {metrics.MicroAccuracy:F4}");
        Console.WriteLine($"LogLoss:          {metrics.LogLoss:F4}");
        Console.WriteLine($"LogLossReduction: {metrics.LogLossReduction:F4}");

        // Retrain on full dataset for production model
        var fullModel = pipeline.Fit(data);
        mlContext.Model.Save(fullModel, data.Schema, modelPath);
        Console.WriteLine($"Model saved to {modelPath}");

        return modelPath;
    }
}

